import math

def min_Jumps(point, jump_length):
    """
    Minimum number of jumps of length jump_length to reach point from origin.
    point can be (x, y) or a scalar d (target on x-axis).
    """
    if isinstance(point, (tuple, list)):
        x, y = point[0], point[1]
        d = math.hypot(x, y)
    else:
        d = abs(point)

    a = jump_length
    b = jump_length

    if d == 0:
        return 0
    if d == a:
        return 1
    if d < b:
        return 2
    return math.ceil(d / b)
